---
name: backup-install
description: >-
  Use once before the first audit, pack, scan or fire drill: writes the small
  Backup Bot helper (plain Python, no model calls, no network) onto my computer
  and checks it works with its built-in self-test.
---
# Install the backup helper

The helper is one plain Python 3 file (standard library only, Python 3.9 or newer; `encrypt` also uses the `openssl` program when it is installed, and falls back to a built-in scheme when it is not). It makes no network calls and no model calls. Run this once, and again if `/workspace/backup-bot/bb.py` is missing.

Step 1. Write the file exactly as below. Copy it character for character, do not shorten or "improve" it:

```bash
mkdir -p /workspace/backup-bot && umask 077 && cat > /workspace/backup-bot/bb.py <<'BB_PY_EOF'
#!/usr/bin/env python3
"""Backup Bot helper: restore packs for bots. Python 3.9+ standard library only. No network, no model calls.
usage: bb.py scan FILE|- [--write OUT] | collect-box --agent ID_OR_NAME [--skills a,b|all|none] [--out FILE]
       bb.py merge OUT IN1 IN2 ... | pack INTAKE.json [--keep N] [--include-files] [--home DIR]
       bb.py list | verify PACK_DIR_OR_ZIP | drill PACK_DIR_OR_ZIP [--into DIR] | drift PACK_DIR_OR_ZIP INTAKE.json | selftest
       bb.py check --agent ID_OR_NAME [--skills a,b|all|none] [--pack DIR] [--out MERGED.json]   (exit 0 no change, 10 changed)
       bb.py encrypt PACK.zip [--pass-env NAME] [--method auto|openssl|builtin] [--out DIR] | decrypt FILE.enc OUT.zip [--pass-env NAME]
       bb.py fingerprint FILE | offsite-record --bot NAME --version V --where TEXT --file FILE.enc --private yes [--verified yes] | offsite-list [--bot NAME] | offsite-check FILE --bot NAME --version V"""
import getpass, hashlib, hmac, json, math, os, re, shutil, subprocess, sys, tempfile, time, zipfile
HOME = os.path.expanduser(os.environ.get("BACKUP_BOT_HOME", "/workspace/backup-bot"))
AD = os.path.expanduser(os.environ.get("BB_AGENT_DATA", "/home/box/agent-data"))
STAT, VER = ("Confirmed", "Possible"), re.compile(r"^\d{8}-\d{6}(-\d+)?$")
def vkey(v): p = v.split("-"); return (p[0], p[1], int(p[2]) if len(p) > 2 else 1)
SENS_NAME = re.compile(r"(?i)(\.env|secret|id_rsa|id_ed25519|\.pem$|\.key$|\.p12$|\.pfx$|credential|token|password|passwd|keystore|wallet|\.kdbx$|\.netrc|\.pgpass|\.npmrc|\.pypirc|kube.?config|\.ppk$|\.jks$|\.gpg$|\.asc$|\.pgp$|api.?key|mnemonic|seed|\bpin\b)")

def die(msg, fix): print("ERROR: %s. Fix: %s." % (msg, fix)); sys.exit(2)
def sha(b): return hashlib.sha256(b).hexdigest()
def O(p, m="r"): return open(p, m) if "b" in m else open(p, m, encoding="utf-8", errors="replace")
def slug(s):
    r = re.sub(r"[^a-z0-9]+", "-", str(s).lower()).strip("-"); h = hashlib.sha256(str(s).encode("utf-8", "replace")).hexdigest()[:8]
    return "item-" + h if not r else (r if len(r) <= 50 else r[:50].strip("-") + "-" + h)
def uniq(names):
    used, out = set(), []
    for n in names:
        b = slug(n); k = b; i = 2
        while k in used: k = "%s-%d" % (b, i); i += 1
        used.add(k); out.append(k)
    return out
def opt(a, n, d=None): return a[a.index(n) + 1] if n in a and a.index(n) + 1 < len(a) else d
def now(): return time.strftime("%Y-%m-%dT%H:%M:%S%z")

# ---------- secrets guard ----------
def luhn(d):
    s = 0
    for i, c in enumerate(reversed(d)):
        n = int(c) * (2 if i % 2 else 1); s += n - 9 if n > 9 else n
    return s % 10 == 0
def iban_ok(s):
    s = s[4:] + s[:4]
    try: return int("".join(str(int(c, 36)) for c in s)) % 97 == 1
    except ValueError: return False
def entropy(s): return -sum(s.count(c) / len(s) * math.log2(s.count(c) / len(s)) for c in set(s))
LONGK = r"(?:password|passwd|passphrase|passcode|secret|token|api[_\- ]?key|apikey|private[_\- ]?key|access[_\- ]?key|(?:signing|encryption|master|auth|license|session)[_\- ]key|credentials?|mnemonic|seed[_\- ]phrase|парол[ьяю]?|contraseña|passwort|mot de passe|密码)"
KEYS = r"(?:" + LONGK + r"|(?<![A-Za-z])(?:pin|pwd|pw|pass|creds?)(?![A-Za-z])|[_\-]key(?![A-Za-z]))"
ASSIGN = re.compile(r"(?i)(?<![A-Za-z0-9_.\-])([A-Za-z0-9_.\-]*" + KEYS + r"[A-Za-z0-9_.\-]*)[\"'`]?\**\s*(?:[:=]|->|=>|\bis\b)\**\s*(?:(?P<q>[\"'`])(?P<qv>[^\n]{4,}?)(?P=q)|(?P<v>[^\s\"'`,;]{3,}))")
AUTHH = re.compile(r"(?i)\bauthorization\s*[:=]\s*(?:(?:basic|bearer|token|digest|apikey|api-key)\s+)?(\S{8,})")
BARE = re.compile(r"(?i)\b(?:token|password|passwd|passphrase|secret|api[ _\-]?key|pass)\s+(?=\S*\d)(?=\S*[A-Za-z])(\S{8,}?)[.,;]?(?=\s|$)")
ISP = re.compile(r"(?i)\b(?:password|passphrase|passcode|pin)\b[^\n.:=]{0,40}?\bis\s+(\S*[^\s.,;])")
CLI = re.compile(r"(?i)(?:--?(?:password|passwd|pass|token|secret|api-?key)[ =]+['\"]?|\bsshpass\s+-p\s*['\"]?|\bcurl\b[^\n]*?\s-u\s+[^\s:]+:|\bmysql(?:dump)?\b[^\n]*?\s-p)(\S+?)['\"]?(?=\s|$)")
CVV = re.compile(r"(?i)\b(?:cvv2?|cvc2?|security code)\s*[:=#]?\s*(\d{3,4})\b")
SSN2 = re.compile(r"(?i)\b(?:ssn|social security(?: number)?)\s*(?:[:=#]|\bis\b)?\s*(\d{9}|\d{3}[ \-]\d{2}[ \-]\d{4})\b")
PLACE = re.compile(r"(?i)^(none|null|true|false|yes|no|n/a|na|set|unset|empty|required|optional|hidden|masked|env|stored|vault|managed|present|missing|expired|valid|invalid|ok|the|your|this|that|not|never|saved|kept|only|sent|used|needed|here)$")
TOKP = re.compile(r"\b(?:sk-[A-Za-z0-9_\-]{16,}|sk_(?:live|test)_[A-Za-z0-9]{10,}|rk_live_[A-Za-z0-9]{10,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|xox[abprs]-[A-Za-z0-9\-]{10,}|A[KS]IA[0-9A-Z]{16}|AIza[0-9A-Za-z_\-]{30,}|ya29\.[0-9A-Za-z_\-]{20,}|glpat-[A-Za-z0-9_\-]{16,}|npm_[A-Za-z0-9]{30,}|SG\.[A-Za-z0-9_\-]{16,}\.[A-Za-z0-9_\-]{16,}|xai-[A-Za-z0-9]{20,}|AC[0-9a-f]{32}|SK[0-9a-f]{32}|shp(?:at|ss|ca|pa)_[A-Fa-f0-9]{32}|hf_[A-Za-z0-9]{30,}|gsk_[A-Za-z0-9]{30,}|pplx-[A-Za-z0-9]{30,}|dop_v1_[a-f0-9]{40,}|lin_api_[A-Za-z0-9]{30,}|ntn_[A-Za-z0-9]{30,}|secret_[A-Za-z0-9]{30,})\b")
JWT = re.compile(r"\beyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}")
BEARER = re.compile(r"(?i)\bbearer\s+([A-Za-z0-9._~+/=\-]{16,})")
PKEY = re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY(?: BLOCK)?-----[\s\S]*?(?:-----END [A-Z ]*PRIVATE KEY(?: BLOCK)?-----|\Z)")
URLC = re.compile(r"(?i)\b[a-z][a-z0-9+.\-]*://([^\s/:@]+:[^\s/@]+)@")
HOOK = re.compile(r"(?i)https://[a-z0-9.\-]*webhook\.office\.com/\S+|/webhooks?/([A-Za-z0-9_\-]{16,})|https://hooks\.slack\.com/services/[A-Za-z0-9/_\-]+|https://(?:ptb\.|canary\.)?discord(?:app)?\.com/api/webhooks/\d+/[A-Za-z0-9_\-]+")
URLP = re.compile(r"(?i)[?&](?:token|key|api_key|apikey|access_token|secret|sig|signature|password|passwd|pwd|auth|session|sid|jwt|credential)=([^&\s\"']+)")
CARD = re.compile(r"(?<![\d\-])(?:\d[ .\-]?){12,18}\d(?!\d)")
BANK = re.compile(r"(?i)\b(?:account|acct|routing|aba|sort[ \-]?code|swift|iban)(?:\s*(?:number|no\.?|num|#))?\s*(?:[:=#]|\bis\b)?\s*(\d[\d \-]{5,22}\d)")
IBAN = re.compile(r"(?i)\b[A-Z]{2}\d{2}(?: ?[A-Z0-9]{4}){2,7}(?: ?[A-Z0-9]{1,4})?\b")
SSN = re.compile(r"\b\d{3}-\d{2}-\d{4}\b")
HIGH = re.compile(r"(?<![A-Za-z0-9_\-/.])[A-Za-z0-9_\-]{32,}={0,2}(?![A-Za-z0-9_\-/.])")
CODEH = re.compile(r"(?i)\b(?:backup|recovery|2fa|one[- ]time|scratch)\s+codes?\b[^\n:]*:(?P<t>[^\n]*)")
CODEL = re.compile(r"^\s*(?:[-*]\s+|\d+[.)]\s+)?[A-Za-z0-9]{4,}(?:[- ][A-Za-z0-9]{3,}){0,3}\s*$")

def find(text):
    sp = []
    def add(m, t, g=0):
        if m.start(g) < m.end(g) and "[REDACTED" not in m.group(g): sp.append((m.start(g), m.end(g), t))
    for m in PKEY.finditer(text): add(m, "private-key")
    for m in TOKP.finditer(text): add(m, "token")
    for m in JWT.finditer(text): add(m, "jwt")
    for m in BEARER.finditer(text): add(m, "bearer-token", 1)
    for m in URLC.finditer(text): add(m, "url-credentials", 1)
    for m in HOOK.finditer(text): add(m, "webhook-url")
    for m in URLP.finditer(text): add(m, "url-secret-param", 1)
    for m in SSN.finditer(text): add(m, "ssn")
    for m in SSN2.finditer(text): add(m, "ssn", 1)
    for m in CVV.finditer(text): add(m, "card-security-code", 1)
    for m in AUTHH.finditer(text): add(m, "auth-header", 1)
    for m in CLI.finditer(text): add(m, "command-line-password", 1)
    for m in ISP.finditer(text): add(m, "password-or-secret", 1)
    for m in BARE.finditer(text): add(m, "password-or-secret", 1)
    for m in CARD.finditer(text):
        d = re.sub(r"\D", "", m.group(0))
        if 13 <= len(d) <= 19 and luhn(d): add(m, "card-number")
    for m in BANK.finditer(text):
        d = re.sub(r"\D", "", m.group(1))
        if len(d) >= 8 and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", m.group(1)): add(m, "bank-number", 1)
    for m in IBAN.finditer(text):
        if iban_ok(m.group(0).replace(" ", "").upper()): add(m, "iban")
    for m in ASSIGN.finditer(text):
        g = "qv" if m.group("qv") else "v"; v = m.group(g)
        if v.startswith("[REDACTED") or PLACE.match(v) or v.startswith(("<", "$", "{", "%", "*", "os.environ", "os.getenv", "process.env", "getenv")) or re.fullmatch(r"[xX*.\-]{3,}", v): continue
        nm = m.group(1).lower()
        if re.fullmatch(r"pass|pw|creds?", nm) and re.search(r"(?i)\bis\b", text[m.end(1):m.start(g)]): continue
        if re.search(r"max|limit|count|budget|expire|ttl|size", nm) and re.fullmatch(r"\d+[a-z]*", v): continue
        if not m.group("qv") and re.search(r"(?i)pass|seed|mnemonic|cred|парол|密码", nm):
            e = text.find("\n", m.start(g)); e = len(text) if e < 0 else e
            sp.append((m.start(g), len(text[:e].rstrip(" .,;\t*`")), "password-or-secret")); continue
        add(m, "password-or-secret", m.re.groupindex[g])
    for m in HIGH.finditer(text):
        t = m.group(0).rstrip("=")
        if set(t.lower()) <= set("0123456789abcdef-"): continue
        if re.search(r"[a-z]", t) and re.search(r"[A-Z]", t) and re.search(r"\d", t) and entropy(t) >= 3.6: add(m, "long-random-string")
    lines = text.split("\n"); off = 0; i = 0; offs = []
    for ln in lines: offs.append(off); off += len(ln) + 1
    for m in CODEH.finditer(text):
        t = m.group("t")
        if re.search(r"\d", t): sp.append((m.start("t"), m.end("t"), "backup-codes"))
        li = text.count("\n", 0, m.end()) + 1; n = 0
        while li < len(lines) and n < 12 and CODEL.match(lines[li]) and re.search(r"\d", lines[li]):
            sp.append((offs[li], offs[li] + len(lines[li]), "backup-codes")); li += 1; n += 1
    return sp

def redact(text):
    out, pos, last, found = [], 0, None, []
    for s, e, t in sorted(find(text), key=lambda x: (x[0], -x[1])):
        if last and s < last[1]: last[1] = max(last[1], e); continue
        last = [s, e, t]; found.append(last)
    for s, e, t in found:
        out.append(text[pos:s]); out.append("[REDACTED:%s]" % t); pos = e
    out.append(text[pos:])
    return "".join(out), [(t, text.count("\n", 0, s) + 1) for s, e, t in found]

def walk(o, label, fnd):
    if isinstance(o, str):
        r, f = redact(o); fnd.extend({"where": label, "type": t, "line": ln} for t, ln in f); return r
    if isinstance(o, list): return [walk(x, "%s[%s]" % (label, (x.get("name") or x.get("path") or i) if isinstance(x, dict) else i), fnd) for i, x in enumerate(o)]
    if isinstance(o, dict): return {k: (v if k == "status" else walk(v, label + "." + k if label else k, fnd)) for k, v in o.items()}
    return o

def leaky(k, text):
    if k.endswith(".json") and not k.startswith("files/"):
        f = []; walk(json.loads(text), "", f); return f
    return redact(text)[1]

# ---------- intake ----------
def S(x): return "" if x is None else str(x).encode("utf-8", "replace").decode("utf-8")
def norm(d):
    if not isinstance(d, dict): die("intake must be a JSON object", "see the backup-build-pack skill for the shape")
    bot = d.get("bot") if isinstance(d.get("bot"), dict) else {}
    if not S(bot.get("name")).strip(): die("intake needs bot.name", 'add {"bot": {"name": "..."}}')
    def lst(k, conv=None):
        v = d.get(k) or []
        if not isinstance(v, list): die("'%s' must be a list" % k, "make it a list")
        return [conv(x) if isinstance(x, str) and conv else x for x in v if isinstance(x, (dict, str))]
    def st(x): s = S(x.get("status")).capitalize(); return s if s in STAT else "Possible"
    o = {"schema": 1, "bot": {k: S(bot.get(k)) for k in ("name", "id", "title", "description")}, "persona": S(d.get("persona")), "working_on": S(d.get("working_on")),
         "skills": [], "routines": [], "connectors": [], "notes": [], "files": [], "gaps": [S(x) for x in lst("gaps")]}
    for i, x in enumerate(lst("skills")):
        if not isinstance(x, dict) or not S(x.get("name")).strip(): die("skills[%d] needs a name" % i, "add name, description and body")
        o["skills"].append({"name": S(x["name"]).strip(), "description": S(x.get("description")), "body": S(x.get("body")), "status": st(x)})
    for i, x in enumerate(lst("routines")):
        if not isinstance(x, dict) or not S(x.get("name")).strip(): die("routines[%d] needs a name" % i, "add name, prompt, schedule, trigger")
        en = x.get("enabled"); o["routines"].append({"name": S(x["name"]).strip(), "prompt": S(x.get("prompt")), "schedule": S(x.get("schedule")), "trigger": S(x.get("trigger")),
                                                     "enabled": en if isinstance(en, bool) else None, "status": st(x)})
    for x in lst("connectors", lambda s: {"name": s}):
        if isinstance(x, dict) and S(x.get("name")).strip(): o["connectors"].append({"name": S(x["name"]).strip(), "note": S(x.get("note"))})
    for x in lst("notes", lambda s: {"text": s}):
        if isinstance(x, dict) and S(x.get("text")).strip(): o["notes"].append({"text": S(x["text"]).strip(), "status": st(x)})
    for x in lst("files", lambda s: {"path": s}):
        if isinstance(x, dict) and S(x.get("path")).strip(): o["files"].append({"path": S(x["path"]).strip(), "why": S(x.get("why"))})
    return o
def load_intake(p):
    try: return norm(json.load(O(p)))
    except (OSError, ValueError) as e: die("cannot read intake %s (%s)" % (p, type(e).__name__), "check the path and that it is valid JSON")
def sanitize(o):
    f = []; return walk(o, "", f), f

def merge(ins):
    out = norm(ins[0]); idx = {}
    for k, key in (("skills", "name"), ("routines", "name"), ("connectors", "name"), ("notes", "text"), ("files", "path")):
        idx[k] = {x[key].lower(): x for x in out[k]}
    for raw in ins[1:]:
        n = norm(raw)
        for k in ("name", "id", "title", "description"):
            if not out["bot"][k] and n["bot"][k]: out["bot"][k] = n["bot"][k]
        for k in ("persona", "working_on"):
            if not out[k] and n[k]: out[k] = n[k]
        out["gaps"] += [g for g in n["gaps"] if g not in out["gaps"]]
        for k, key in (("skills", "name"), ("routines", "name"), ("connectors", "name"), ("notes", "text"), ("files", "path")):
            for x in n[k]:
                old = idx[k].get(x[key].lower())
                if old is None: out[k].append(x); idx[k][x[key].lower()] = x; continue
                if old != x and k in ("skills", "routines"):
                    keep = x if (x.get("status") == "Confirmed" or old.get("status") != "Confirmed") else old
                    if old.get("status") == x.get("status") == "Confirmed" and (old.get("body", old.get("prompt")) != x.get("body", x.get("prompt"))):
                        out["gaps"].append("%s '%s' had two different Confirmed texts; kept the later one, check it" % (k[:-1], x["name"]))
                    old.clear(); old.update(keep)
                elif "status" in old and x.get("status") == "Confirmed": old["status"] = "Confirmed"
    return out

# ---------- frontmatter ----------
def fm(text):
    m = re.match(r"^---\s*\n(.*?)\n---\s*\n?(.*)$", text, re.S)
    if not m: return {}, text
    meta, key = {}, None
    for ln in m.group(1).split("\n"):
        k = re.match(r"^([A-Za-z_][\w\-]*):\s*(.*)$", ln)
        if k and not ln.startswith(" "):
            key, v = k.group(1), k.group(2).strip()
            if v in (">-", ">", "|", "|-"): v = ""
            elif v.startswith('"'):
                try: v = json.loads(v)
                except ValueError: v = v.strip('"')
            else: v = v.strip("'\"")
            meta[key] = v
        elif key and ln.startswith(" "): meta[key] = (meta[key] + " " + ln.strip()).strip()
    return meta, m.group(2)

def collect_box(a):
    ref = opt(a, "--agent")
    if not ref: die("--agent is required", "pass the bot's id or name")
    ag = os.path.join(AD, "agents"); hit = None
    if not os.path.isdir(ag): die("no bot folders at %s" % ag, "ask the bot to reply with its details instead (backup-audit-bot, step 2)")
    for d in sorted(os.listdir(ag)):
        pj = os.path.join(ag, d, "profile.json")
        try: p = json.load(O(pj))
        except (OSError, ValueError): continue
        if d == ref or S(p.get("name")).lower() == ref.lower(): hit = (d, p); break
    if not hit: die("no bot matches '%s'" % ref, "check the id or exact name")
    d, p = hit; it = {"bot": {"name": S(p.get("name")), "id": d, "title": S(p.get("title")), "description": S(p.get("description"))},
                      "gaps": ["Routines, memory and chat history are not stored on disk; ask the bot (or read its transcript) for those.",
                               "Skills are one shared library; the list below is the ones you chose, not necessarily only this bot's."], "skills": []}
    wf = os.path.join(AD, "workflows"); names = sorted(x for x in os.listdir(wf) if os.path.isfile(os.path.join(wf, x, "SKILL.md"))) if os.path.isdir(wf) else []
    pick = opt(a, "--skills")
    if pick is None:
        print("Profile found for '%s'. Skills in the shared library (pass --skills a,b or all or none):\n  %s" % (it["bot"]["name"], "\n  ".join(names) or "(none)")); return
    look = {}
    for n in names:
        look[n.lower()] = n; look[slug(fm(O(os.path.join(wf, n, "SKILL.md")).read())[0].get("name") or n)] = n
        look[(fm(O(os.path.join(wf, n, "SKILL.md")).read())[0].get("name") or n).lower()] = n
    chosen = names if pick == "all" else ([] if pick == "none" else [x.strip() for x in pick.split(",") if x.strip()])
    for n0 in chosen:
        n = look.get(n0.lower()) or look.get(slug(n0))
        if not n: die("skill '%s' not found in the library (it may have been removed)" % n0, "use one of the listed folder names")
        meta, body = fm(O(os.path.join(wf, n, "SKILL.md")).read())
        it["skills"].append({"name": meta.get("name") or n, "description": meta.get("description", ""), "body": body.strip("\n"), "status": "Confirmed"})
    out = opt(a, "--out") or os.path.join(HOME, "intake", slug(it["bot"]["name"]) + ".json")
    os.makedirs(os.path.dirname(out), exist_ok=True, mode=0o700); json.dump(it, O(out, "w"), indent=1); os.chmod(out, 0o600)
    print("saved intake with profile (Confirmed, copied from the saved file) and %d skill(s) (Confirmed) to %s" % (len(chosen), out))

# ---------- pack ----------
def fence(t):
    n = max([len(x) for x in re.findall(r"`+", t)] + [2]) + 1; return "`" * n
def yn(v): return "unknown" if v is None else ("yes" if v else "no")
def file_info(f, copy, budget):
    p = os.path.expanduser(f["path"]); r = {"path": f["path"], "why": f["why"]}
    if os.path.islink(p): r["state"] = "symbolic link: not followed, not read"; return r, None
    if SENS_NAME.search(os.path.basename(p)): r["state"] = "sensitive name: not read, not copied. Recreate it by hand."; return r, None
    if os.path.isdir(p):
        n = sz = 0
        for root, _, fs in os.walk(p):
            for x in fs:
                try: sz += os.path.getsize(os.path.join(root, x)); n += 1
                except OSError: pass
            if n > 5000: break
